window.RA_DATA = window.RA_DATA || {};
window.RA_DATA.lines = [
  { id: "eonm-s1", kind: "scene", book_id: "emily-of-new-moon", place_ids: ["ca-montgomery-home"], location: "Opening chapters", location_zh: "开头几章", text_en: "Orphaned at eleven, Emily Byrd Starr is taken to New Moon, her proud aunts' old farm at Blair Water. She keeps writing letters to her dead father, and treasures the rare 'flash', a moment when she glimpses beauty behind a curtain, that tells her she will be a writer.", text_zh: "十一岁成了孤儿的艾米莉·伯德·斯塔尔，被带到布莱尔湖边姨妈们骄傲的老农庄“新月山庄”。她一直给死去的父亲写信，珍惜偶尔出现的“闪光”——在那一瞬间她仿佛看见帷幕后的美，也知道自己将来会成为作家。", highlight_en: ["New Moon"], highlight_zh: ["新月山庄"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Emily_of_New_Moon" },
  { id: "fp-s1", kind: "scene", book_id: "fugitive-pieces", place_ids: ["ca-raymore"], location: "Book 2", location_zh: "第二部", text_en: "Ben, a Toronto professor born to Holocaust survivors, remembers the night in October 1954 when Hurricane Hazel's flood wrecked his family's house in Weston. The storm feeds his lifelong study of weather, and leads him at last to the poet Jakob Beer's notebooks.", text_zh: "本是多伦多的一位教授，父母都是大屠杀幸存者。他记得 1954 年 10 月那一夜，飓风“黑兹尔”的洪水毁了他家在韦斯顿的房子。这场风暴让他一生研究天气，最后也把他引向诗人雅各布·比尔的笔记。", highlight_en: ["Hurricane Hazel"], highlight_zh: ["黑兹尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Fugitive_Pieces" },
  { id: "ngm-s1", kind: "scene", book_id: "no-great-mischief", place_ids: ["ca-cape-breton"], location: "Opening", location_zh: "开头", text_en: "The family story Alexander MacDonald grows up with: in 1779 Calum Ruadh sailed from Moidart to Cape Breton, and his dog, left behind on the Scottish shore, swam out after the boat until they hauled her aboard. His descendants, the clann Chalum Ruaidh, still carry the red hair and the loyalty.", text_zh: "亚历山大·麦克唐纳从小听着的家族故事：1779 年，红发卡勒姆从莫伊达特渡海来布雷顿角，他留在苏格兰岸上的狗一直游着追赶小船，直到大家把它拉上船。他的后代“红发卡勒姆家族”至今还有那头红发，也还有那份忠诚。", highlight_en: ["Cape Breton"], highlight_zh: ["布雷顿角"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/No_Great_Mischief" },
  { id: "ts-s1", kind: "scene", book_id: "two-solitudes", place_ids: ["ca-montreal"], location: "Parts 3–4", location_zh: "第三至四部", text_en: "Paul Tallard, son of a French-Canadian landowner and an Irish mother, grows up between Quebec's two peoples and falls in love with Heather Methuen, daughter of a rich English Montreal family. The novel takes its title from Rilke: love consists in two solitudes that protect and touch and greet each other.", text_zh: "保罗·塔拉尔的父亲是法裔加拿大地主，母亲是爱尔兰人。他在魁北克两个民族之间长大，爱上了蒙特利尔英裔富家女希瑟·梅休恩。书名出自里尔克：爱就是两种孤独彼此守护、相触、致意。", highlight_en: ["Montreal"], highlight_zh: ["蒙特利尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Hugh_MacLennan" },
  { id: "bv-s1", kind: "scene", book_id: "barneys-version", place_ids: ["ca-montreal"], location: "Opening", location_zh: "开头", text_en: "Barney Panofsky, a cantankerous Montreal television producer in his sixties, sits down to write his memoirs to answer the charge that has followed him for decades: that he murdered his best friend Boogie at his cottage in the Laurentians. Boogie's body was never found.", text_zh: "六十多岁、脾气古怪的蒙特利尔电视制片人巴尼·帕诺夫斯基坐下来写回忆录，回应纠缠了他几十年的指控：说他在劳伦琴山的小屋里杀了最好的朋友布吉。布吉的尸体始终没有找到。", highlight_en: ["Montreal"], highlight_zh: ["蒙特利尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Barney%27s_Version" },
  { id: "tw-s1", kind: "scene", book_id: "the-wars", place_ids: ["ca-toronto"], location: "Part 1", location_zh: "第一部", text_en: "In Toronto in 1915, Robert Ross's frail sister Rowena dies after a fall from her wheelchair, and his mother orders him to kill the rabbits Rowena loved. He cannot do it. Soon after, he enlists, and goes to the war in Flanders.", text_zh: "1915 年在多伦多，罗伯特·罗斯体弱的妹妹罗维娜从轮椅上摔下来死了，母亲命令他杀掉罗维娜心爱的兔子。他下不了手。不久他就参了军，去了弗兰德斯的战场。", highlight_en: ["Toronto"], highlight_zh: ["多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Wars_(novel)" },
  { id: "eb-s1", kind: "scene", book_id: "englishmans-boy", place_ids: ["ca-cypress-massacre"], location: "Alternating chapters, 1873", location_zh: "1873 年的章节", text_en: "In 1920s Hollywood, a young Canadian writer, Harry Vincent, is sent to find Shorty McAdoo, an old cowboy actor, and get his story. McAdoo was the 'Englishman's boy' among the wolfers who rode north in 1873 after stolen horses and massacred an Assiniboine camp in the Cypress Hills.", text_zh: "20 世纪 20 年代的好莱坞，年轻的加拿大编剧哈里·文森特受命去找老牛仔演员肖蒂·麦卡杜，挖出他的故事。1873 年，一群猎狼人为追回被偷的马北上，在塞浦路斯丘屠杀了一个阿西尼博因营地，麦卡杜就是其中那个“英国人的男孩”。", highlight_en: ["Cypress Hills"], highlight_zh: ["塞浦路斯丘"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Englishman%27s_Boy" },
  { id: "ag-s1", kind: "scene", book_id: "alias-grace", place_ids: ["ca-kingston-pen"], location: "1859", location_zh: "1859 年", text_en: "Grace Marks has been in Kingston Penitentiary for sixteen years for the 1843 murders of Thomas Kinnear and his housekeeper Nancy Montgomery, though she says she remembers nothing. Dr Simon Jordan, a young American doctor of the mind, comes to talk with her in the governor's house while she sews quilts, trying to recover what happened.", text_zh: "格蕾丝·马克斯因 1843 年托马斯·金尼尔和管家南希·蒙哥马利被杀一案，已在金斯顿监狱关了十六年，她自己却说什么都不记得。年轻的美国精神科医生西蒙·乔丹来到典狱长家里，趁她缝被子时和她交谈，想找回当年的真相。", highlight_en: ["Kingston Penitentiary"], highlight_zh: ["金斯顿监狱"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Alias_Grace" },
  { id: "ba-s1", kind: "scene", book_id: "blind-assassin", place_ids: ["ca-toronto"], location: "Opening", location_zh: "开头", text_en: "Ten days after the war ends in 1945, Laura Chase drives a car off a bridge in Toronto. Decades later Iris, old and alone, sets down what really happened to the Chase family, between her account and the chapters of a novel, The Blind Assassin, published under Laura's name.", text_zh: "1945 年战争结束十天后，劳拉·蔡斯开车冲下了多伦多的一座桥。几十年后，年老孤独的艾丽丝写下蔡斯家真正发生的事，与以劳拉之名出版的小说《盲刺客》的章节交错在一起。", highlight_en: ["Toronto"], highlight_zh: ["多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Blind_Assassin" },
  { id: "tt-s1", kind: "scene", book_id: "the-testaments", place_ids: ["ca-toronto"], location: "Daisy's testimony", location_zh: "黛西的证词", text_en: "Daisy grows up in Toronto with Neil and Melanie, who run a second-hand clothing shop called The Clothes Hound and secretly help women escape from Gilead. On her sixteenth birthday they are killed by Gileadean agents, and she learns she is Baby Nicole, the child smuggled out of Gilead years before.", text_zh: "黛西在多伦多由尼尔和梅兰妮抚养长大，他们开着一家叫“衣服猎犬”的二手服装店，暗中帮助妇女逃离基列。她十六岁生日那天，两人被基列特工杀害；她这才知道，自己就是多年前被偷偷带出基列的“小妮可”。", highlight_en: ["Toronto"], highlight_zh: ["多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Testaments" },
  { id: "sos-s1", kind: "scene", book_id: "songs-of-a-sourdough", place_ids: ["ca-lake-laberge"], location: "The Cremation of Sam McGee", location_zh: "《萨姆·麦吉的火化》", text_en: "Sam McGee from Tennessee, always cold in the Yukon, makes his partner promise to cremate him if he dies on the trail. When Sam freezes to death, the narrator hauls the body to Lake Laberge, fires up the boiler of the derelict steamer Alice May and puts him in; when he looks in later, Sam is sitting up, warm at last.", text_zh: "从田纳西来的萨姆·麦吉在育空总觉得冷，要搭档答应：他要是死在路上，就把他火化。萨姆冻死后，叙述者把尸体拖到拉伯奇湖，点燃搁浅的破汽船“爱丽丝·梅号”的锅炉把他塞进去；过一会儿往里一看，萨姆正坐着，终于暖和了。", highlight_en: ["Lake Laberge"], highlight_zh: ["拉伯奇湖"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Cremation_of_Sam_McGee" },
  { id: "cow-s1", kind: "scene", book_id: "us-call-of-the-wild", place_ids: ["ca-dawson"], location: "Chapter 6", location_zh: "第 6 章", text_en: "In the Eldorado Saloon in Dawson, John Thornton boasts that Buck can start a sled loaded with a thousand pounds of flour and pull it a hundred yards. A bet of sixteen hundred dollars is laid; out in the frozen street Buck breaks the runners free and hauls the load the whole distance.", text_zh: "在道森的黄金国酒馆里，约翰·桑顿夸口说巴克能拉动装着一千磅面粉的雪橇走一百码。有人押上一千六百美元；巴克在结冰的街上把冻住的滑板拉松，一口气拉完了全程。", highlight_en: ["Dawson"], highlight_zh: ["道森"], status: "draft", fact_source: "https://www.gutenberg.org/ebooks/215" },
  { id: "bon-s1", kind: "scene", book_id: "book-of-negroes", place_ids: ["ca-birchtown"], location: "Book 3", location_zh: "第三卷", text_en: "Having registered her name in the Book of Negroes to be evacuated from New York with the Black Loyalists, Aminata Diallo reaches Nova Scotia in 1783 and lives at Birchtown, where the promised land grants never come and families winter in pits in the ground.", text_zh: "阿米娜塔·迪亚洛在《黑人之书》上登记了名字，随黑人效忠派从纽约撤离，1783 年来到新斯科舍，住在伯奇敦。答应给的土地始终没有兑现，一家家人只能住在地坑里过冬。", highlight_en: ["Birchtown"], highlight_zh: ["伯奇敦"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Book_of_Negroes_(novel)" },
  { id: "ih-s1", kind: "scene", book_id: "indian-horse", place_ids: ["ca-manitouwadge"], location: "Part 2", location_zh: "第二部", text_en: "At thirteen, Saul Indian Horse leaves St. Jerome's residential school to live with an Ojibway family in Manitouwadge and play for the Moose, an all-Ojibway team. They beat the white teams in the towns along the Trans-Canada Highway, and meet growing hatred for it.", text_zh: "十三岁时，索尔·印第安马离开圣杰罗姆寄宿学校，住进马尼托瓦奇的一户奥吉布瓦人家，为全是奥吉布瓦人的“驼鹿队”打球。他们在横加公路沿线小镇赢了一支又一支白人球队，也招来越来越深的仇恨。", highlight_en: ["Manitouwadge"], highlight_zh: ["马尼托瓦奇"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Indian_Horse" },
  { id: "sd-s1", kind: "scene", book_id: "stone-diaries", place_ids: ["ca-tyndall"], location: "Chapter 1, Birth, 1905", location_zh: "第 1 章《出生，1905》", text_en: "In the limestone village of Tyndall, Manitoba, the enormous Mercy Stone Goodwill, who has not even realised she is pregnant, gives birth in her kitchen and dies. The baby, Daisy, grows up to live nearly the whole century, and the novel tells her life as a kind of autobiography written by someone else.", text_zh: "在曼尼托巴的石灰岩小村廷代尔，身材庞大的默西·斯通·古德威尔连自己怀孕都没察觉，就在厨房里生下孩子，随即死去。这个叫戴西的婴儿活了将近整整一个世纪；小说把她的一生写成一部由别人执笔的“自传”。", highlight_en: ["Tyndall"], highlight_zh: ["廷代尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Stone_Diaries" },
  { id: "fb-s1", kind: "scene", book_id: "fifth-business", place_ids: ["ca-thamesville"], location: "Part 1", location_zh: "第一部", text_en: "On 27 December 1908 in Deptford, Boy Staunton throws a snowball with a stone in it at his friend Dunstan Ramsay, who ducks. It strikes Mrs Dempster, the Baptist minister's pregnant wife, who gives birth that night to a premature son, Paul. Dunstan carries the guilt all his life.", text_zh: "1908 年 12 月 27 日，在德普特福德，博伊·斯汤顿朝朋友邓斯坦·拉姆齐扔了一个裹着石头的雪球，邓斯坦一躲，雪球砸中了浸信会牧师怀孕的妻子登普斯特太太。她当晚早产，生下儿子保罗。邓斯坦为此背负了一生的愧疚。", highlight_en: ["Deptford"], highlight_zh: ["德普特福德"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Fifth_Business" },
  { id: "ack-s1", kind: "scene", book_id: "complicated-kindness", place_ids: ["ca-steinbach"], location: "Throughout", location_zh: "全书", text_en: "Sixteen-year-old Nomi Nickel lives with her father in East Village, a Mennonite town whose church runs every life. Her sister Tash left first and then her mother Trudie vanished; Nomi drifts through school and a future in the chicken plant, trying to understand why they left.", text_zh: "十六岁的诺米·尼克尔和父亲住在东村，一个由门诺派教会主宰一切的小镇。先是姐姐塔什离开，接着母亲特鲁迪也不见了；诺米在学校里浑浑噩噩，眼看将来只能去养鸡场工作，一直想弄明白她们为什么走。", highlight_en: ["East Village"], highlight_zh: ["东村"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/A_Complicated_Kindness" },
  { id: "amps-s1", kind: "scene", book_id: "all-my-puny-sorrows", place_ids: ["ca-winnipeg"], location: "Throughout", location_zh: "全书", text_en: "Elf von Riesen, a celebrated concert pianist, no longer wants to live. Her younger sister Yoli, whose own life is a mess, keeps flying home to Winnipeg to sit by her hospital bed, torn between keeping her alive and honouring what Elf asks of her.", text_zh: "著名钢琴家埃尔芙·冯·里森不想再活下去。妹妹约莉自己的生活一团糟，却一次次飞回温尼伯守在姐姐的病床前，在留住姐姐和尊重姐姐的请求之间左右为难。", highlight_en: ["Winnipeg"], highlight_zh: ["温尼伯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/All_My_Puny_Sorrows" },
  { id: "rib-s1", kind: "scene", book_id: "roughing-it-in-the-bush", place_ids: ["ca-lakefield"], location: "Chapters on the bush farm, 1834–1839", location_zh: "丛林农场诸章，1834—1839 年", text_en: "In 1834 the Moodies take up a bush lot in Douro Township near Lakefield, beside Susanna's brother Samuel Strickland and her sister Catharine Parr Traill. Raised a gentlewoman in Suffolk, Susanna learns to clear land, to make coffee from dandelion roots, and to keep the farm and children alive alone while her husband serves in the militia during the 1837 rebellion.", text_zh: "1834 年，穆迪一家在莱克菲尔德附近的杜罗镇区分到一块林地，紧挨着苏珊娜的弟弟塞缪尔·斯特里克兰和姐姐凯瑟琳·帕尔·特雷尔。在萨福克以淑女身份长大的苏珊娜学会了开荒、用蒲公英根煮咖啡；1837 年叛乱时丈夫去民兵队服役，她独自撑起农场、养活孩子。", highlight_en: ["Douro"], highlight_zh: ["杜罗"], status: "draft", fact_source: "https://www.gutenberg.org/ebooks/4389" },
  { id: "div-s1", kind: "scene", book_id: "the-diviners", place_ids: ["ca-lakefield"], location: "Throughout", location_zh: "全书", text_en: "Morag Gunn, a novelist in her late forties who grew up poor in the prairie town of Manawaka, lives alone in an old log house on the river at McConnell's Landing. Her daughter Pique has gone west; Morag writes, remembers, and quarrels in her head with the ghost of the pioneer Catharine Parr Traill.", text_zh: "四十多岁的女作家莫拉格·冈恩在草原小镇马纳瓦卡的穷人家长大，如今独自住在麦康奈尔码头河边的一座老木屋里。女儿皮克去了西部；莫拉格写作、回忆，在心里和拓荒女作家凯瑟琳·帕尔·特雷尔的幽灵争论。", highlight_en: ["McConnell's Landing"], highlight_zh: ["麦康奈尔码头"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Margaret_Laurence" },
  { id: "ls-s1", kind: "scene", book_id: "the-last-spike", place_ids: ["ca-craigellachie"], location: "Final chapter", location_zh: "最后一章", text_en: "At Craigellachie on 7 November 1885, Donald Smith bends the first spike he swings at, then drives in a plain iron one. William Van Horne, asked for a speech, says only that the work has been done well in every way, and the first train rolls west to the Pacific.", text_zh: "1885 年 11 月 7 日在克雷盖拉奇，唐纳德·史密斯第一锤就把道钉敲弯了，又换一颗普通的铁钉敲进去。被请上前讲话的威廉·范霍恩只说了一句：这活儿干得样样都好。随后第一列火车向西开往太平洋。", highlight_en: ["Craigellachie"], highlight_zh: ["克雷盖拉奇"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Last_Spike_(Canadian_Pacific_Railway)" },
  { id: "kl-s1", kind: "scene", book_id: "klondike-berton", place_ids: ["ca-discovery-claim"], location: "Part 1", location_zh: "第一部", text_en: "In August 1896, acting on a tip from the prospector Robert Henderson, George Carmack, his brother-in-law Skookum Jim and their nephew Dawson Charlie find gold lying between the slabs of rock in Rabbit Creek. They rename it Bonanza, and within two years tens of thousands are on their way to Dawson.", text_zh: "1896 年 8 月，听了探矿人罗伯特·亨德森的指点，乔治·卡马克和妻兄斯库库姆·吉姆、外甥道森·查理在兔溪的石板缝里看见了金子。他们把小溪改名“博南扎”；不到两年，几万人涌向道森。", highlight_en: ["Rabbit Creek"], highlight_zh: ["兔溪"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Klondike_Gold_Rush" },
  { id: "kw-s1", kind: "scene", book_id: "klee-wyck", place_ids: ["ca-ucluelet"], location: "Ucluelet", location_zh: "《尤克卢利特》", text_en: "In 1899 the young Emily Carr stays with the missionaries at Ucluelet on the west coast of Vancouver Island. The Nuu-chah-nulth villagers, amused by how she laughs, call her Klee Wyck, 'Laughing One', the name she later gave her book.", text_zh: "1899 年，年轻的埃米莉·卡尔住在温哥华岛西岸尤克卢利特的传教士家里。努查努尔特村民觉得她笑起来很好玩，叫她“克利·维克”，意思是“爱笑的人”，她后来就用这个名字做了书名。", highlight_en: ["Klee Wyck"], highlight_zh: ["克利·维克"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Klee_Wyck" },
  { id: "ru-s1", kind: "scene", book_id: "ru-thuy", place_ids: ["ca-granby"], location: "Fragments", location_zh: "片段", text_en: "After the boat and the Malaysian refugee camp, the ten-year-old narrator and her family are settled in Granby, Quebec, in 1979. She remembers the town as a warm cocoon: neighbours who brought winter clothes, teachers who took turns to help, a first taste of being safe.", text_zh: "坐过难民船、住过马来西亚难民营之后，十岁的叙述者一家 1979 年被安置在魁北克的格兰比。她把这座小城记成一个温暖的茧：邻居送来冬衣，老师们轮流帮忙，她第一次尝到安全的滋味。", highlight_en: ["Granby"], highlight_zh: ["格兰比"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Kim_Th%C3%BAy" },
  { id: "mac-s1", kind: "scene", book_id: "mercy-among-the-children", place_ids: ["ca-miramichi"], location: "Part 1", location_zh: "第一部", text_en: "As a boy in the Miramichi, Sydney Henderson pushes a playmate off a roof and, believing he has killed him, promises God never to raise his hand against anyone again. He keeps the vow all his life, and the town, taking his gentleness for weakness, turns on him and his family.", text_zh: "在米拉米奇长大的西德尼·亨德森小时候把一个玩伴推下屋顶，以为对方死了，便向上帝发誓再也不对任何人动手。他一辈子守着这个誓言；镇上的人却把他的温和当成软弱，转而欺负他和他的家人。", highlight_en: ["Miramichi"], highlight_zh: ["米拉米奇"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Mercy_Among_the_Children" },
  { id: "bm-s1", kind: "scene", book_id: "bishops-man", place_ids: ["ca-creignish"], location: "Part 1", location_zh: "第一部", text_en: "In the 1990s, as the abuse scandals in the Church break open, Father Duncan MacAskill, who for years quietly moved troublesome priests on for his bishop, is himself sent away to the parish of Creignish on Cape Breton, near where he grew up, and told to stay out of sight.", text_zh: "20 世纪 90 年代，教会的性侵丑闻接连曝光。多年来替主教悄悄把惹麻烦的神父调走的邓肯·麦卡斯基尔神父，自己也被派到布雷顿角的克雷格尼什教区，离他长大的地方不远，并被叮嘱别露面。", highlight_en: ["Creignish"], highlight_zh: ["克雷格尼什"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Bishop%27s_Man" },
  { id: "fli-s1", kind: "scene", book_id: "five-little-indians", place_ids: ["ca-dtes"], location: "Throughout", location_zh: "全书", text_en: "Kenny, Lucy, Clara, Howie and Maisie, taken as children to a residential school on an island off Vancouver Island, are turned out at sixteen into 1960s Vancouver with nothing. Over the following decades they find their way through the East End's rooming houses, bars and protests, holding on to one another.", text_zh: "肯尼、露西、克拉拉、豪伊和梅茜小时候被带到温哥华岛外一座小岛上的寄宿学校，十六岁时被两手空空地赶到 20 世纪 60 年代的温哥华。此后几十年，他们在东区的出租屋、酒吧和抗议活动中摸索前行，彼此扶持。", highlight_en: ["Vancouver"], highlight_zh: ["温哥华"], status: "draft", fact_source: "https://www.harpercollins.ca/9781443459181/five-little-indians/" },
  { id: "wb-s1", kind: "scene", book_id: "washington-black", place_ids: ["ca-halifax-waterfront"], location: "Later chapters", location_zh: "后半部", text_en: "Alone after Titch disappears, Wash settles in Halifax, Nova Scotia, and spends his days drawing the creatures of the shore. There he meets the marine naturalist Mr Goff and his daughter Tanna, and with them plans an 'ocean house' to keep sea creatures alive for people to see.", text_zh: "蒂奇失踪后，孤身一人的瓦什在新斯科舍的哈利法克斯住下来，整天画岸边的海洋生物。他在这里结识了海洋博物学家戈夫先生和他的女儿坦娜，和他们一起计划建一座“海洋之屋”，把海洋生物养起来给人看。", highlight_en: ["Halifax"], highlight_zh: ["哈利法克斯"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Washington_Black" },
  { id: "dwc-s1", kind: "scene", book_id: "day-the-world-came-to-town", place_ids: ["ca-gander"], location: "11–15 September 2001", location_zh: "2001 年 9 月 11—15 日", text_en: "When American airspace closes on 11 September, 38 planes are ordered down at Gander. The town of about 10,000 opens its schools, churches and homes to some 6,700 stranded passengers for days, cooking, lending clothes and showing them around Newfoundland.", text_zh: "9 月 11 日美国领空关闭，38 架飞机奉命降落在甘德。这座约一万人的小镇打开学校、教堂和自家大门，接待了约 6700 名滞留乘客好几天，给他们做饭、借衣服，带他们看纽芬兰。", highlight_en: ["Gander"], highlight_zh: ["甘德"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Operation_Yellow_Ribbon" },
  { id: "lna-s1", kind: "scene", book_id: "late-nights-on-air", place_ids: ["ca-yellowknife"], location: "Throughout", location_zh: "全书", text_en: "In 1975 Harry Boyd, a broadcaster whose career has gone wrong, comes back north to run the little radio station in Yellowknife. Around the station, as the town argues over the Mackenzie Valley Pipeline, its staff fall in and out of love and plan a canoe trip across the Barren Lands.", text_zh: "1975 年，事业失意的播音员哈里·博伊德回到北方，主管耶洛奈夫的小电台。镇上为麦肯齐河谷输油管道争论不休，电台的同事们在这里相爱又分开，还计划划独木舟穿越贫瘠地带。", highlight_en: ["Yellowknife"], highlight_zh: ["耶洛奈夫"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Late_Nights_on_Air" },
  { id: "mm-s1", kind: "scene", book_id: "mrs-mike", place_ids: ["ca-grouard"], location: "Throughout", location_zh: "全书", text_en: "Sent from Boston to Calgary in 1907 to recover from pleurisy, sixteen-year-old Kathy O'Fallon marries Sergeant Mike Flannigan of the Royal North-West Mounted Police and follows him to remote northern posts such as Grouard on Lesser Slave Lake, where she loses her two children to diphtheria.", text_zh: "1907 年，十六岁的凯茜·奥法伦从波士顿来卡尔加里养病，嫁给了皇家西北骑警的迈克·弗拉尼根中士，跟着他去北方偏远的哨所，其中就有小奴湖边的格鲁阿尔；她的两个孩子在那里死于白喉。", highlight_en: ["Grouard"], highlight_zh: ["格鲁阿尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Mrs._Mike" },
  { id: "tbs-s1", kind: "scene", book_id: "through-black-spruce", place_ids: ["ca-moose-factory"], location: "Throughout", location_zh: "全书", text_en: "Will Bird, an old Cree bush pilot, lies in a coma in the hospital at Moose Factory after a beating. His niece Annie sits by his bed and tells him of her year searching for her missing sister in Toronto, Montreal and New York, while in his mind he tells the story of the feud that put him there.", text_zh: "年老的克里族丛林飞行员威尔·伯德被人打成重伤，昏迷躺在穆斯工厂的医院里。侄女安妮守在床边，对他讲自己这一年在多伦多、蒙特利尔和纽约寻找失踪的妹妹；而他在心里讲着把自己害到这一步的那场仇怨。", highlight_en: ["Moose Factory"], highlight_zh: ["穆斯工厂"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Through_Black_Spruce" },
  // —— 11-22 quotations from English Wikisource, replacing the placeholder scene notes (add_en3.py) ——
  { id: "aogg-1", book_id: "anne-of-green-gables", place_ids: ["ca-green-gables"], location: "Chapter 1", location_zh: "第一章", text_en: "Accordingly after tea Mrs. Rachel set out; she had not far to go; the big, rambling, orchard-embowered house where the Cuthberts lived was a scant quarter of a mile up the road from Lynde’s Hollow. To be sure, the long lane made it a good deal further. Matthew Cuthbert’s father, as shy and silent as his son after him, had got as far away as he possibly could from his fellow men without actually retreating into the woods when he founded his homestead. Green Gables was built at the furthest edge of his cleared land and there it was to this day, barely visible from the main road along which all the other Avonlea houses were so sociably situated. Mrs. Rachel Lynde did not call living in such a place living at all.", highlight_en: ["Green Gables"], text_zh: "于是喝过茶后，雷切尔太太就出发了；她要去的地方不远，卡斯伯特家住的那座大而散漫、掩映在果园里的房子，离林德谷沿路往上只有四分之一英里不到。不过那条长长的小路倒让路程远了不少。马修·卡斯伯特的父亲和后来的儿子一样腼腆寡言，当初建宅时，他在不至于退进树林的前提下，尽可能远离了他的同类。绿山墙就建在他开垦出来的土地的最远处，至今仍在那里，从大路上几乎看不见，而埃文利的其他人家都亲亲热热地沿着大路排开。雷切尔·林德太太认为住在那样的地方根本算不上过日子。", highlight_zh: ["绿山墙"], translation: "original", status: "draft", checked: "English Wikisource, Anne of Green Gables (1908)/Chapter I, 2026-11-22" },
  { id: "wf-1", book_id: "white-fang", place_ids: ["ca-dawson"], location: "Part 4, chapter 4", location_zh: "第四部第四章", text_en: "\"Wait till I get back to Dawson,\" Beauty Smith threatened. \"I'll have the law on you.\"\n\"If you open your mouth when you get back to Dawson, I'll have you run out of town. Understand?\"\nBeauty Smith replied with a grunt.\n\"Understand?\" the other thundered with abrupt fierceness.\n\"Yes,\" Beauty Smith grunted, shrinking away.", highlight_en: ["Dawson"], text_zh: "“等我回到道森再说，”美人史密斯威胁道，“我要告你。”\n“你回到道森要是敢开口，我就把你赶出城去。明白吗？”\n美人史密斯哼了一声。\n“明白吗？”对方突然厉声大喝。\n“明白，”美人史密斯哼哼着，缩着身子退开了。", highlight_zh: ["道森"], translation: "original", status: "draft", checked: "English Wikisource, White Fang/4.4, 2026-11-22" },
  // —— 11-24: second pack, the two books left out of the first (tools/content/batches/add_ca2.py) ——
  { id: "ca-em-1", kind: "scene", book_id: "season-in-the-life-of-emmanuel", place_ids: ["ca-quebec-city"], location: "The novel as a whole", location_zh: "全书", text_en: "A large, poor farm family in rural Quebec, ruled by the grandmother Antoinette, in the season of the birth of Emmanuel, the sixteenth child. The novel follows his teenage brothers and sisters, Jean-Le Maigre, Pomme, Héloïse and the one called Septième, each in some kind of revolt against the family and the church-ruled world around it.", text_zh: "魁北克乡间一个贫穷的农家大家庭，由祖母安托瓦妮特当家，时间是第十六个孩子埃马纽埃尔出生的那一季。小说跟着他十几岁的哥哥姐姐——让-勒迈格尔、波姆、埃卢瓦兹和被叫作“第七”的那一个——他们各自以某种方式反抗着家庭，反抗着由教会主宰的周遭世界。", highlight_en: ["Quebec"], highlight_zh: ["魁北克"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/A_Season_in_the_Life_of_Emmanuel; https://www.ebsco.com/research-starters/literature-and-writing/season-life-emmanuel-marie-claire-blais" },
  { id: "ca-be-1", kind: "scene", book_id: "bear-engel", place_ids: ["ca-algoma"], location: "The novel as a whole", location_zh: "全书", text_en: "Lou, a reserved librarian and archivist at a historical institute in Toronto, is sent for a summer to an island estate on a remote lake in northern Ontario, left to the institute with the library of a nineteenth-century colonel, to catalogue the books. The island has one other inhabitant, a bear, and her slow communion with it and with the wild changes her.", text_zh: "露是多伦多一家历史研究所里拘谨的图书管理员兼档案员。研究所继承了安大略北部一座偏远湖泊中的小岛庄园和一位 19 世纪上校的藏书，派她去待一个夏天，给藏书编目。岛上还有另一个住户——一头熊；她与熊、与荒野慢慢的交融，改变了她。", highlight_en: ["northern Ontario"], highlight_zh: ["安大略北部"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Bear_(novel); https://thecanadianencyclopedia.ca/en/article/marian-engel; https://www.indigo.ca/products/bear-kanata-classics-edition" },
  // —— 11-28 Canada rule-v2 re-check, batch 1: Atlantic Canada (add_ca_v2_1128_1.py) ——
  { id: "folyk-s1", kind: "scene", book_id: "fall-on-your-knees", place_ids: ["ca-new-waterford"], location: "Prologue, “Silent Pictures”, and throughout", location_zh: "序章《无声的照片》，及全书", text_en: "At the turn of the twentieth century the piano tuner James Piper elopes with thirteen-year-old Materia Mahmoud, daughter of a wealthy Lebanese family, and settles in the coal town of New Waterford on Cape Breton Island. Their daughters are Kathleen, the gifted eldest, whom James adores and sends to New York to train as an opera singer, then Mercedes, Frances and Lily. The novel opens with the house at 191 Water Street, New Waterford, and Ma on the day she died, 23 June 1919, and follows the sisters through the First World War, the mines and the Depression to Jazz-Age Harlem, as they hold together around a terrible family secret.", text_zh: "二十世纪初，钢琴调音师詹姆斯·派珀和十三岁的玛特丽娅·马哈茂德私奔；她出身富裕的黎巴嫩家庭。两人在布雷顿角岛的煤矿镇新沃特福德安了家，生下几个女儿：长女凯瑟琳天赋过人，詹姆斯对她宠爱有加，送她去纽约学唱歌剧；之后是梅塞德斯、弗朗西丝和莉莉。小说开篇是新沃特福德水街 191 号的那座房子，和“妈妈去世那天”：1919 年 6 月 23 日。故事跟着姐妹们走过第一次世界大战、矿井和大萧条，一直到爵士时代的哈莱姆；她们围着一个可怕的家族秘密，彼此依靠着活下去。", highlight_en: ["Cape Breton Island", "New Waterford"], highlight_zh: ["布雷顿角岛", "新沃特福德"], status: "draft", fact_source: "https://cbra.library.utoronto.ca/items/show/3992; https://www.simonandschuster.net/books/Fall-On-Your-Knees/Ann-Marie-MacDonald/9781451641653; https://en.wikipedia.org/wiki/Fall_on_Your_Knees; https://www.powells.com/book/fall-on-your-knees-9780770429379" },
  { id: "birthhouse-s1", kind: "scene", book_id: "the-birth-house", place_ids: ["ca-scots-bay"], location: "Throughout", location_zh: "全书", text_en: "Dora Rare, the first daughter born to the Rare family in five generations, grows up in the isolated Bay of Fundy village of Scots Bay, where her family descends from a Scottish woman shipwrecked on the bay and a Mi'kmaq man called Silent Rare. As a girl she befriends Miss Marie Babineau, the outspoken Acadian midwife and healer, and at the outbreak of the First World War becomes her apprentice; together they help the women of Scots Bay through difficult labours, infertility and unwanted pregnancies. When the brash obstetrician Gilbert Thomas arrives promising fast, painless childbirth, some of the women begin to doubt Miss B.'s ways, and after Miss B.'s death Dora carries on alone, against a background of war, the influenza, the Halifax Explosion and the Boston Molasses Flood of 1919.", text_zh: "多拉·雷尔是雷尔家五代人里头一个女儿，在芬迪湾边与世隔绝的斯科茨湾长大；她家的先人是一个在湾里遇上海难的苏格兰女人和一个人称“沉默的雷尔”的米克马克男人。她小时候就和直言不讳的阿卡迪亚接生婆兼草药医玛丽·巴比诺小姐交上了朋友，第一次世界大战开始时做了她的徒弟，两人一起帮斯科茨湾的女人们度过难产、不孕和不想要的怀孕。莽撞的产科医生吉尔伯特·托马斯来到村里，许诺又快又不疼地生孩子，一些女人开始怀疑巴比诺小姐的老办法；巴比诺小姐死后，多拉独自撑了下去。背景是战争、大流感、哈利法克斯大爆炸和 1919 年的波士顿糖蜜洪水。", highlight_en: ["Scots Bay"], highlight_zh: ["斯科茨湾"], status: "draft", fact_source: "https://quillandquire.com/review/the-birth-house/; https://www.goodreads.com/book/show/171102; https://www.4thestate.co.uk/products/the-birth-house-ami-mckay-9780007232826-2/; https://www.biblio.com/0676977731; https://www.thebookbag.co.uk/reviews/The_Birth_House; https://bac-lac.wayback.archive-it.org/web/20071114233355/http://www.cbc.ca/arts/books/birth.html" },
  { id: "colony-s1", kind: "scene", book_id: "colony-of-unrequited-dreams", place_ids: ["ca-st-johns"], location: "Throughout", location_zh: "全书", text_en: "A fictionalised life of Joey Smallwood, the politician who brought Newfoundland into Confederation with Canada in 1949, told mostly in his own voice and intertwined with that of the invented journalist and satirist Sheilagh Fielding. Smallwood grows up on the Brow, the poorest part of St. John's, and goes to school in the city; he covers the seal hunt and sees men die in a storm on the ice, spends years in New York as a struggling socialist journalist, and comes home to walk the railway line across the whole island in 1925 to unionise the railway workers. The novel follows the first half of his life as he drives on into politics, pushing aside his love for Fielding, while the mystery of a letter attributed to her runs beneath it all.", text_zh: "这是乔伊·斯莫尔伍德的小说化传记：1949 年正是这位政治家把纽芬兰带进了加拿大联邦。故事大半由他自己讲述，和虚构的记者、讽刺作家希拉·菲尔丁的声音交织在一起。斯莫尔伍德在圣约翰斯最穷的“坡顶”长大，在城里上学；他报道过猎海豹，亲眼看着人们在冰上的风暴里死去；在纽约做了几年潦倒的社会主义记者，回到纽芬兰后，1925 年沿着铁路徒步横穿全岛，去把铁路工人组织进工会。小说写的是他前半生：他一路闯进政坛，把对菲尔丁的爱搁在一边，而一封据说出自她手的信的谜团，一直潜伏在故事底下。", highlight_en: ["St. John's", "Newfoundland"], highlight_zh: ["圣约翰斯", "纽芬兰"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Colony_of_Unrequited_Dreams; https://bookpage.com/reviews/570-wayne-johnston-review-fiction/; https://quillandquire.com/?p=72737; https://www.themodernnovel.org/americas/other-americas/canada/johnston/colony/; https://openlibrary.org/isbn/0676971822" },
  { id: "annabel-s1", kind: "scene", book_id: "annabel-winter", place_ids: ["ca-st-johns"], location: "Later chapters", location_zh: "后半部", text_en: "In March 1968, in the village of Croydon Harbour on the south-east Labrador coast, Jacinta Blake gives birth in her bathtub to a child with both male and female anatomy. Her husband Treadway, a trapper, decides to raise the child as a boy, Wayne; only the parents and their friend Thomasina, the midwife, know, and Thomasina privately calls the child Annabel, after her own drowned daughter. Wayne grows up in a hunting world, dreams of synchronized swimming, and at puberty a medical emergency puts him in hospital, though he learns its full causes only years later. After high school he moves to St. John's, the city his mother came from, to find out the truth; there he stops the masculinising medication, lets his body change, and comes to accept himself, later making peace with his father.", text_zh: "1968 年 3 月，在拉布拉多东南海岸的克罗伊登港，杰辛塔·布莱克在浴缸里生下一个同时具有男女两种身体特征的孩子。丈夫特雷德韦是个设陷阱打猎的人，他决定把孩子当男孩养，取名韦恩；知道真相的只有父母和他们的朋友、接生的托马西娜，托马西娜私下叫这个孩子“安娜贝尔”，那是她自己淹死的女儿的名字。韦恩在一个打猎的男人世界里长大，却梦想着花样游泳；到了青春期，一场急病让他住进医院，个中原因他多年后才完全知道。高中毕业后，他搬到母亲的故乡圣约翰斯去弄清真相，在那里停掉了让自己男性化的药，任身体自然改变，慢慢接纳了真实的自己，后来也和父亲和解。", highlight_en: ["St. John's", "Labrador"], highlight_zh: ["圣约翰斯", "拉布拉多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Annabel_(Winter_novel); https://quillandquire.com/review/annabel/; https://erudit.org/en/journals/scl/2014-v39-n1-scl04781/1062365ar.pdf; https://mtlreviewofbooks.ca/reviews/annabel/; https://www.theglobeandmail.com/arts/books-and-media/annabel-by-kathleen-winter/article4392478/" },
  // —— 11-28 Canada rule-v2 re-check, batch 2: Quebec (add_ca_v2_1128_2.py) ——
  { id: "lullabies-s1", kind: "scene", book_id: "lullabies-for-little-criminals", place_ids: ["ca-saint-laurent"], location: "Throughout", location_zh: "全书", text_en: "Baby is twelve. Her mother died soon after she was born, and her father Jules, who was still a teenager then, is slipping deeper into heroin; the two move from one cheap room to the next around Montreal's red-light district, among junkies, pimps and abused children, and Jules leaves her alone for weeks at a time. While he is in hospital with tuberculosis she is put into a foster home; back with him, she runs away from his rages and falls in with a pimp, Alphonse, who draws her into prostitution and heroin, and she spends a month in juvenile detention. Baby tells it all with a child's eye. The novel won Canada Reads in 2007.", text_zh: "贝比十二岁。母亲在她出生后不久就死了，父亲朱尔斯那时自己还是个少年，如今海洛因越吸越深；父女俩在蒙特利尔红灯区一带从一个廉价房间搬到另一个，身边是瘾君子、皮条客和受虐的孩子，朱尔斯常常一走就把她丢下好几个星期。他因肺结核住院时，她被送进寄养家庭；回到他身边后，她躲开他的暴脾气跑了出去，落到皮条客阿方斯手里，被他拖进卖身和海洛因，还在少年拘留所里待了一个月。这一切都是透过贝比孩子的眼睛讲出来的。这本书获得了 2007 年“加拿大共读”冠军。", highlight_en: ["Montreal"], highlight_zh: ["蒙特利尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Lullabies_for_Little_Criminals; https://mtlreviewofbooks.ca/reviews/lullabies-for-little-criminals/; https://kirkusreviews.com/book-reviews/heather-oneill/lullabies-for-little-criminals/" },
  { id: "tinflute-s1", kind: "scene", book_id: "the-tin-flute", place_ids: ["ca-saint-henri"], location: "Throughout", location_zh: "全书", text_en: "Montreal, February to May 1940: the war has begun but Saint-Henri is still sunk in the Depression. Florentine Lacasse, nineteen, a waitress at the Five and Ten, keeps her large family afloat; her mother Rose-Anna looks after the children, and her father Azarius drifts from one failed job to the next. Florentine dreams of a better life and falls for Jean Lévesque, an ambitious, well-off young machinist; he tires of her and passes her on to his friend Emmanuel Létourneau, a soldier on leave, who falls in love with her. Jean forces himself on Florentine and leaves her pregnant; she keeps it secret and marries Emmanuel, who has promised to look after her. The book won the Prix Femina in 1947.", text_zh: "蒙特利尔，1940 年 2 月到 5 月：战争已经开始，圣亨利区却还陷在大萧条里。十九岁的弗洛朗蒂娜·拉卡斯在“五分一毛”店当女招待，靠她撑着一大家子；母亲罗丝-安娜照看孩子们，父亲阿扎里于斯一份差事接一份地丢。弗洛朗蒂娜盼着过上更好的日子，爱上了野心勃勃、手头宽裕的年轻机修工让·莱韦克；他厌了她，把她推给朋友、休假的士兵埃马纽埃尔·莱图尔诺，埃马纽埃尔爱上了她。让强行占有了弗洛朗蒂娜，让她怀了孕；她瞒住此事，嫁给了答应照顾她的埃马纽埃尔。这本书 1947 年获得费米娜奖。", highlight_en: ["Saint-Henri", "Montreal"], highlight_zh: ["圣亨利", "蒙特利尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Tin_Flute" },
  { id: "stilllife-s1", kind: "scene", book_id: "still-life-penny", place_ids: ["ca-knowlton"], location: "Throughout", location_zh: "全书", text_en: "In the early morning mist of Thanksgiving Sunday, Jane Neal, seventy-six, a retired schoolteacher, is found dead on a deer path in the woods outside Three Pines, a village south of Montreal so small it has no police of its own, killed by an arrow through the heart. Everyone takes it for a hunting accident. Chief Inspector Armand Gamache of the Sûreté du Québec, sent with his team from Montreal, is not so sure; Jane had only just agreed to show one of her paintings, Fair Day, in an exhibition for the first time, and her friend and neighbour, the painter Clara Morrow, notices the slight difference between Fair Day and Jane's murals that holds the key. The book introduced Gamache and Three Pines.", text_zh: "感恩节星期天清晨的薄雾里，七十六岁的退休教师简·尼尔被发现死在三松村外树林里的一条鹿径上，一支箭穿心而过；三松村在蒙特利尔以南，小到连自己的警察都没有。人人都以为是狩猎意外。魁北克省警的首席探长阿尔芒·加马什带着手下从蒙特利尔赶来，却不这么看：简刚刚第一次答应把自己的一幅画《集市日》拿去参展，她的朋友和邻居、画家克拉拉·莫罗注意到《集市日》和简的壁画之间一处细小的差别，那正是破案的钥匙。加马什和三松村都是从这本书开始的。", highlight_en: ["Three Pines"], highlight_zh: ["三松村"], status: "draft", fact_source: "https://kirkusreviews.com/book-reviews/louise-penny/still-life-3; https://www.powells.com/biblio/74-9780312948559-0; https://www.supersummary.com/still-life/summary; https://www.shelf-awareness.com/theshelf/2006-08-16/mandahla_i_still_life_i_reviewed.html; https://thecanadianencyclopedia.ca/en/article/louise-penny" },
  { id: "gursky-s1", kind: "scene", book_id: "solomon-gursky", place_ids: ["ca-montreal"], location: "Throughout", location_zh: "全书", text_en: "Moses Berger, a brilliant Montreal scholar ruined by drink and son of the failed poet L. B. Berger, has been obsessed since boyhood with the Gurskys: the three brothers Bernard, Solomon and Morrie, bootleggers turned whisky barons, whose McTavish distillery empire many readers take for the Bronfmans' Seagram. Solomon, the boldest, vanished in a plane crash; Moses suspects he is still alive. Tracing the family back, Moses finds the patriarch Ephraim, a small-time London criminal who talked his way onto Franklin's doomed 1845 Arctic expedition, survived it, and set himself up as a messiah among the Inuit, some of whom still bear the name Gor-ski. The story ranges from the London underworld through the Arctic and the Prohibition prairies to the Eastern Townships and the brothers' neighbouring mansions on the slope of Mount Royal.", text_zh: "摩西·伯格是蒙特利尔一位被酒毁掉的才子，失意诗人 L. B. 伯格的儿子，从小就迷上了古尔斯基家族：伯纳德、所罗门、莫里三兄弟，先是私酒贩子，后来成了威士忌大亨，许多读者认为他们的麦克塔维什酒业帝国写的就是布朗夫曼家族的施格兰。最大胆的所罗门死于一场空难，摩西却怀疑他还活着。顺着家族往上追，摩西找到了始祖以法莲：伦敦的一个小毛贼，混上了富兰克林 1845 年那支注定覆灭的北极探险队，居然活了下来，在因纽特人中间做起了弥赛亚，至今还有因纽特人姓“戈尔斯基”。故事从伦敦的黑社会，经过北极、禁酒令时期的草原，一直写到东镇，写到三兄弟在皇家山坡上比邻而建的豪宅。", highlight_en: ["Montreal", "Mount Royal"], highlight_zh: ["蒙特利尔", "皇家山"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Solomon_Gursky_Was_Here; https://www.kirkusreviews.com/book-reviews/a/mordecai-richler-3/solomon-gursky-was-here; https://publishersweekly.com/9780394539959; https://www.ebsco.com/research-starters/literature-and-writing/solomon-gursky-was-here-mordecai-richler; https://ojs.library.ubc.ca/index.php/canlit/article/view/192830/189343; https://banq.overdrive.com/media/1762254; https://fiftybooksproject.blogspot.com/2020/11/solomon-gursky-was-here-by-mordecai.html" },
  // —— 11-28 Canada rule-v2 re-check, batch 3: Toronto (add_ca_v2_1128_3.py) ——
  { id: "skinlion-s1", kind: "scene", book_id: "in-the-skin-of-a-lion", place_ids: ["ca-bloor-viaduct"], location: "Book One, “The Bridge”, and throughout", location_zh: "第一部《桥》，及全书", text_en: "Toronto in the early twentieth century, told through the immigrants who built it but were left out of its official history. The Bloor Street Viaduct is going up across the Don Valley to carry traffic, water and electricity into the city; the Commissioner of Public Works, R. C. Harris, often visits it at night. One night five nuns wander onto the unfinished bridge and one falls; Nicholas Temelcoff, a Macedonian bridge-worker who speaks little English, catches her in mid-air and dislocates his arm. Patrick Lewis, who grew up in the logging village of Depot Creek, comes to the city to search for the vanished theatre millionaire Ambrose Small, falls for his mistress Clara Dickens and later for Alice Gull, works as a dynamiter on the tunnel under Lake Ontario for Harris's water filtration plant, and at last turns on Harris himself. Hana and Caravaggio go on into The English Patient.", text_zh: "二十世纪初的多伦多，由那些建起这座城、却被正史遗忘的移民来讲。布卢尔街高架桥正在当河谷上架起来，要把车流、水和电送进城；公共工程专员 R. C. 哈里斯常在夜里来桥上看看。一天夜里，五个修女走上没有完工的桥，其中一个掉了下去；不太会说英语的马其顿桥工尼古拉斯·泰梅尔科夫在半空中接住了她，自己的胳膊却脱了臼。在伐木村德波溪长大的帕特里克·刘易斯来到城里，寻找失踪的剧院富豪安布罗斯·斯莫尔，爱上了他的情妇克拉拉·狄更斯，后来又爱上爱丽丝·古尔；他在安大略湖底为哈里斯的滤水厂挖隧道当爆破工，最后把矛头对准了哈里斯本人。哈娜和卡拉瓦乔后来又走进了《英国病人》。", highlight_en: ["Bloor Street Viaduct", "Don Valley"], highlight_zh: ["布卢尔街高架桥", "当河谷"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/In_the_Skin_of_a_Lion; https://en.wikipedia.org/wiki/Prince_Edward_Viaduct" },
  { id: "fifteendogs-s1", kind: "scene", book_id: "fifteen-dogs", place_ids: ["ca-high-park"], location: "Throughout", location_zh: "全书", text_en: "Over drinks at the Wheat Sheaf Tavern in Toronto, the gods Hermes and Apollo argue whether animals given human intelligence and language would be happier or unhappier than humans, and wager a year's servitude on it. They give the gift to fifteen dogs kennelled at a nearby veterinary clinic. The dogs escape and make their way to High Park, where they set up a new society; Atticus, a Neapolitan mastiff, becomes its leader, while Prince, a mongrel, takes to the new language and becomes a poet, and Majnoun, a black poodle, forms a bond with a woman named Nira. The new language divides the pack, and the gods watch to see whether the gift can make any of the dogs happy.", text_zh: "在多伦多的麦捆酒馆里喝着酒，赫尔墨斯和阿波罗两位神争论起来：如果动物有了人的智力和语言，它们会比人更幸福还是更不幸？他们押上一年的奴役打了个赌，把这份礼物给了附近一家兽医诊所里寄养的十五只狗。狗们逃了出来，来到海伊公园，在那里建起了一个新社会：那不勒斯獒阿提克斯当了首领；杂种狗普林斯迷上了新语言，成了诗人；黑色贵宾犬马吉努和一个叫妮拉的女人结下了情谊。新语言让狗群起了纷争，两位神在一旁看着，看这份礼物能不能让哪只狗幸福。", highlight_en: ["High Park", "Toronto"], highlight_zh: ["海伊公园", "多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Fifteen_Dogs" },
  { id: "stationeleven-s1", kind: "scene", book_id: "station-eleven", place_ids: ["ca-elgin-theatre"], location: "Opening chapters", location_zh: "开头几章", text_en: "During a production of King Lear at the Elgin Theatre in Toronto, the actor playing Lear, Arthur Leander, has a heart attack on stage. Jeevan Chaudhary, a former paparazzo training as a paramedic, rushes to the stage and tries in vain to revive him, then comforts Kirsten Raymonde, an eight-year-old girl in the cast. Walking home through the snow, Jeevan gets a call from a doctor friend: the Georgia Flu is spreading fast and kills almost everyone it touches. Twenty years later Kirsten travels the Great Lakes region with the Traveling Symphony, a troupe that performs Shakespeare and music for the scattered survivors, still carrying the two comic books, Station Eleven, that Arthur gave her before he died.", text_zh: "多伦多的埃尔金剧院正在上演《李尔王》，扮演李尔的演员亚瑟·利安德在台上心脏病发作。曾经当过狗仔、正在受训做急救员的吉万·乔杜里冲上舞台，徒劳地抢救他，随后安慰剧组里八岁的小演员柯尔斯滕·雷蒙德。吉万踏着雪走回家时，一个当医生的朋友打来电话：“格鲁吉亚流感”正迅速蔓延，染上的人几乎无一幸存。二十年后，柯尔斯滕跟着“旅行交响乐团”在五大湖一带巡演，为四散的幸存者演莎士比亚、奏音乐，身上一直带着亚瑟死前送给她的两本漫画，《第十一站》。", highlight_en: ["Elgin Theatre", "Toronto"], highlight_zh: ["埃尔金剧院", "多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Station_Eleven" },
  { id: "robberbride-s1", kind: "scene", book_id: "the-robber-bride", place_ids: ["ca-toronto-islands"], location: "Throughout", location_zh: "全书", text_en: "Toronto, 23 October 1990: three women in their late forties, friends since their student days at the University of Toronto, are having their monthly lunch at the Toxique, a restaurant on Queen Street, when in walks Zenia, the beautiful, lying friend who betrayed each of them and whose funeral they attended five years earlier. Tony is a military historian at the university, Roz a successful businesswoman, and Charis a gentle, New Age yoga teacher who lives in a cottage on the Toronto Island. In flashbacks each remembers how Zenia came into her life with a story made to measure and took her man: to Charis she came in 1970, claiming to be fleeing a violent man and dying of cancer, and Charis took her into her island home. Atwood recast the Grimms' tale of the robber bridegroom as a woman.", text_zh: "多伦多，1990 年 10 月 23 日：三个快五十岁的女人，从多伦多大学读书时就是朋友，正在皇后街的“托克西克”餐馆吃她们每月一次的午饭，泽尼亚走了进来。这个美丽又满口谎言的朋友背叛过她们每一个人，五年前她们还去参加过她的葬礼。托妮在大学里研究军事史，罗兹是成功的女商人，查丽丝是温柔、讲“新时代”的瑜伽老师，住在多伦多岛上的一座小屋里。在回忆里，三个人各自想起泽尼亚怎样带着为她量身编好的故事走进自己的生活，夺走了自己的男人：1970 年她来找查丽丝，说自己在躲一个暴力的男人，又得了癌症快死了，查丽丝便把她接进了岛上的家。阿特伍德把格林童话里的强盗新郎改写成了一个女人。", highlight_en: ["Toronto Island", "Toronto"], highlight_zh: ["多伦多岛", "多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Robber_Bride; https://www.nybooks.com/?p=20197; https://journals.lib.unb.ca/index.php/IFR/article/download/14386/15463/19122; https://readinggroupguides.com/reviews/the-robber-bride; https://www.supersummary.com/the-robber-bride/summary" },
  { id: "engineer-s1", kind: "scene", book_id: "engineer-of-human-souls", place_ids: ["ca-erindale"], location: "Throughout", location_zh: "全书", text_en: "Toronto, winter 1976 to spring 1977. Danny Smiřický, the Czech writer and jazz saxophonist of Škvorecký's earlier novels, left Czechoslovakia in 1968 and now teaches American literature at Edenvale College near Toronto, watching the snow swirl over the campus. The chapters take the names of the writers he lectures on, and his classes of earnest, puzzled Canadian students alternate with letters from friends behind the Iron Curtain, the Czech exile community in Toronto, and memories of his youth in wartime Kostelec, where he chased girls and played the saboteur. Škvorecký called it an entertainment on the old themes of life, women, fate, dreams, the working class, secret agents, love and death; it won the Governor General's Award in 1984.", text_zh: "多伦多，1976 年冬到 1977 年春。丹尼·斯米日茨基就是什克沃雷茨基早先几部小说里那个捷克作家兼爵士萨克斯手，1968 年离开捷克斯洛伐克，如今在多伦多附近的伊登维尔学院教美国文学，望着雪花在校园上空打旋。各章以他讲授的作家命名：他班上认真又困惑的加拿大学生，和铁幕后朋友们的来信、多伦多的捷克流亡圈、战时故乡科斯泰莱茨的青春回忆交替出现，那时他追女孩，也当过一回“破坏分子”。什克沃雷茨基称它是“一部关于生活、女人、命运、梦想、工人阶级、特务、爱情与死亡这些老题目的消遣之作”；它获得了 1984 年的总督奖。", highlight_en: ["Edenvale College", "Toronto"], highlight_zh: ["伊登维尔学院", "多伦多"], status: "draft", fact_source: "https://www.cmreviews.ca/cm/cmarchive/vol13no1/revengineerofhuman.html; https://cbra.library.utoronto.ca/items/show/37175; https://themodernnovel.org/?p=2644; https://nybooks.com/?p=23573; https://www.ebsco.com/research-starters/literature-and-writing/engineer-human-souls-josef-skvorecky; https://www.goodreads.com/book/show/6977371" },
  { id: "catseye-s1", kind: "scene", book_id: "cats-eye", place_ids: ["ca-toronto"], location: "Throughout", location_zh: "全书", text_en: "The painter Elaine Risley comes back to Toronto, the city she grew up in, for a retrospective of her work, and the city brings back her childhood. After a wandering early life with her family, she settles into school in Toronto and is taken up by three girls, Carol, Grace and the clever, domineering Cordelia, who turn her into the object of a slow, smiling cruelty, always presented as an effort to improve her. One winter they throw her hat into a ravine and leave her in the half-frozen creek, where a vision of the Virgin Mary seems to lead her out; only then does she break away. In high school the tables turn on Cordelia, whose life later comes apart, and the cat's-eye marble Elaine kept as a child becomes a motif of her paintings.", text_zh: "画家伊莱恩·里斯利回到她长大的多伦多参加自己的作品回顾展，这座城把她的童年带了回来。随家人四处漂泊过一阵后，她在多伦多入了学，被三个女孩拉进圈子：卡罗尔、格蕾丝和聪明又专横的科迪莉亚。三人对她施以缓慢的、笑眯眯的折磨，嘴上总说是为了让她变好。一个冬天，她们把她的帽子扔进峡谷，任她留在半冻的溪水里，一个圣母玛利亚的幻影似乎领着她爬了出来；直到这时她才挣脱了她们。上了中学，处境反了过来，科迪莉亚后来的生活也四分五裂；伊莱恩小时候珍藏的那颗猫眼弹珠，成了她画里反复出现的意象。", highlight_en: ["Toronto"], highlight_zh: ["多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Cat%27s_Eye_(novel)" },
  { id: "bloodletting-s1", kind: "scene", book_id: "bloodletting-miraculous-cures", place_ids: ["ca-toronto"], location: "Throughout", location_zh: "全书", text_en: "Twelve linked stories follow four young doctors, Ming, Fitzgerald, Chen and Sri, from cramming for medical school in Ottawa to the anatomy lab, the wards and the emergency rooms of Toronto. Ming is accepted to medical school and Fitzgerald is not; she drops him and later marries her lab partner Chen, while Fitz, who follows her into medicine, drifts from job to job, including an air ambulance, and drinks. Near the end comes the SARS outbreak of 2003, with two of them in an isolation ward after treating infected patients. Vincent Lam, a Toronto emergency physician, worked in the emergency department of one of the hospitals hit by SARS.", text_zh: "十二个相互勾连的短篇，跟着四个年轻医生明、菲茨杰拉德、陈和斯里，从在渥太华拼命备考医学院，到解剖室、病房和多伦多的急诊室。明考上了医学院，菲茨杰拉德没考上；她甩了他，后来嫁给了实验搭档陈。菲茨后来也追着她学了医，却在一份份工作之间漂荡，包括空中救护，还酗酒。书的末尾写到 2003 年的非典疫情：他们中两人因为救治病人被关进了隔离病房。作者林伟健就是多伦多的急诊科医生，非典时在一家受疫情冲击的医院急诊室工作。", highlight_en: ["Toronto"], highlight_zh: ["多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Bloodletting_%26_Miraculous_Cures; https://medhum.med.nyu.edu/view/12677; https://www.kirkusreviews.com/book-reviews/vincent-lam/bloodletting-miraculous-cures/; https://journals.library.ualberta.ca/jchla/index.php/jchla/article/download/24051/17875/59476; https://mjm.mcgill.ca/article/download/471/311" },
  { id: "scottpilgrim-s1", kind: "scene", book_id: "scott-pilgrim", place_ids: ["ca-toronto"], location: "Volume 1", location_zh: "第一册", text_en: "In “the mysterious land of Toronto, Canada”, twenty-three-year-old Scott Pilgrim shares a cheap apartment with his gay roommate Wallace, plays bass in the garage band Sex Bob-Omb and is casually dating Knives Chau, a seventeen-year-old high-school girl. Then he dreams of a pink-haired girl on rollerblades and sees her for real at the library, the Wychwood branch of the Toronto Public Library on Bathurst Street: Ramona Flowers, newly arrived from New York, who delivers parcels for Amazon by a shortcut through people's dreams. To date her, he learns, he must defeat her seven evil exes, and at a battle of the bands the first of them, Matthew Patel, crashes through the ceiling. Bryan Lee O'Malley drew the city's real streets, shops and venues into the comic.", text_zh: "在“神秘的国度——加拿大多伦多”，二十三岁的斯科特·皮尔格林和同性恋室友华莱士合住一间廉价公寓，在车库乐队“炸弹鲍勃”里弹贝斯，和十七岁的高中女生诺芙斯·周随便约着会。后来他梦见一个踩着旱冰鞋的粉头发女孩，又在图书馆里见到了真人，那是多伦多公共图书馆在巴瑟斯特街的威奇伍德分馆：她叫拉蒙娜·弗劳尔斯，刚从纽约搬来，替亚马逊送货，抄的近路穿过人们的梦。他得知，要和她交往，就得打败她的七个邪恶前任；在一场乐队比赛上，第一个前任马修·帕特尔破顶而入。布赖恩·李·奥马利把这座城真实的街道、店铺和演出场所都画进了漫画。", highlight_en: ["Toronto"], highlight_zh: ["多伦多"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Scott_Pilgrim; https://scottpilgrim.fandom.com/wiki/Toronto_Public_Library; https://movie-locations.com/movies/s/Scott-Pilgrim-Vs-The-World.php; https://amp.cbc.ca/lite/story/1.3984171" },
  // —— 11-28 Canada rule-v2 re-check, batch 4: Ontario (add_ca_v2_1128_4.py) ——
  { id: "sunshine-q1", book_id: "sunshine-sketches", place_ids: ["ca-orillia"], location: "Chapter I, “The Hostelry of Mr. Smith”", location_zh: "第一章《史密斯先生的旅馆》", text_en: "I don't know whether you know Mariposa. If not, it is of no consequence, for if you know Canada at all, you are probably well acquainted with a dozen towns just like it.\nThere it lies in the sunlight, sloping up from the little lake that spreads out at the foot of the hillside on which the town is built. There is a wharf beside the lake, and lying alongside of it a steamer that is tied to the wharf with two ropes of about the same size as they use on the Lusitania. The steamer goes nowhere in particular, for the lake is landlocked and there is no navigation for the Mariposa Belle except to \"run trips\" on the first of July and the Queen's Birthday, and to take excursions of the Knights of Pythias and the Sons of Temperance to and from the Local Option Townships.\nIn point of geography the lake is called Lake Wissanotti and the river running out of it the Ossawippi, just as the main street of Mariposa is called Missinaba Street and the county Missinaba County.", highlight_en: ["Mariposa", "Lake Wissanotti"], text_zh: "我不知道你知不知道马里波萨。不知道也没关系，因为只要你对加拿大稍有了解，大概就熟悉十来个跟它一模一样的小镇。\n它就躺在阳光里，从山坡脚下铺开的小湖边一路往坡上延伸，小镇就建在这片山坡上。湖边有一座码头，码头旁泊着一艘汽船，拴船的两根缆绳和“卢西塔尼亚号”上用的差不多粗。这艘汽船哪儿也不去，因为这湖四面不通外水，“马里波萨美人号”无处可航，只在七月一日和女王诞辰日“跑几趟”，再载着皮西厄斯骑士会和禁酒之子会的人，往返于那几个实行地方禁酒的镇区。\n从地理上说，这湖叫维萨诺蒂湖，从湖里流出去的河叫奥萨维皮河，正如马里波萨的大街叫米西纳巴街，这个县叫米西纳巴县。", highlight_zh: ["马里波萨", "维萨诺蒂湖"], translation: "original", status: "draft", checked: "English Wikisource, Sunshine Sketches of a Little Town/Chapter I, 2026-11-28" },
  { id: "bestlaid-s1", kind: "scene", book_id: "the-best-laid-plans", place_ids: ["ca-parliament-hill"], location: "Throughout", location_zh: "全书", text_en: "Daniel Addison, a burnt-out speechwriter for the Liberal Leader of the Opposition on Parliament Hill, quits on the eve of an election to teach English at the University of Ottawa. As a last favour he must find a Liberal candidate for Cumberland-Prescott, a riding the party has no hope of winning against the popular Finance Minister, Eric Cameron. He rents the boathouse apartment of Angus McLintock, a crusty Scottish engineering professor mourning his wife and building a hovercraft, and strikes a deal: Daniel will teach Angus's hated English for Engineers class, and Angus will let his name stand, with no campaign and certain to lose. Then a scandal blows away Cameron, Angus is elected, and he decides to see what an honest MP who does not care about re-election can do in the House of Commons.", text_zh: "丹尼尔·艾迪生是国会山上自由党反对党领袖的演讲撰稿人，心力交瘁，在大选前夕辞职，要去渥太华大学教英文。走前他得帮党最后一个忙：给坎伯兰-普雷斯科特选区找一个自由党候选人，在那里，党根本不可能赢过声望正隆的财政部长埃里克·卡梅伦。他租下了安格斯·麦克林托克船库上的公寓：这位脾气倔强的苏格兰工程学教授正为亡妻伤心，还在造一架气垫船。两人做了笔交易：丹尼尔替安格斯教他最讨厌的“工程师英语”课，安格斯则挂名参选，不拉票，稳输。不料一桩丑闻把卡梅伦掀翻，安格斯当选了；他决定看看，一个诚实又不在乎连任的议员，能在下议院里做成什么。", highlight_en: ["Parliament Hill", "Ottawa"], highlight_zh: ["国会山", "渥太华"], status: "draft", fact_source: "https://supersummary.com/the-best-laid-plans/summary; https://paperbackswap.com/Best-Laid-Plans-Terry-Fallis/book/059542872X; https://www.reddeeradvocate.com/columns/a-humorous-birds-eye-view-of-parliamentary-procedures/; https://www.penguinrandomhouse.com/books/47824/the-best-laid-plans-by-terry-fallis/; https://www.kfpl.ca/c/catalogue/record/1.592310; https://terryfallis.com/reviews-of-the-novel/" },
  { id: "orenda-s1", kind: "scene", book_id: "the-orenda", place_ids: ["ca-sainte-marie"], location: "Throughout", location_zh: "全书", text_en: "Wendake, in the early seventeenth century. The story is told in turn by three voices: Bird, a Wendat warrior whose family was murdered by the Haudenosaunee; Snow Falls, a Haudenosaunee girl whose family Bird kills in revenge and whom he takes captive and raises as his daughter; and Christophe, a French Jesuit whom Bird also takes captive and calls the Crow. Christophe, mocked at first for his frailty and his poor grasp of the language, sets out to convert the Wendat; Champlain gives Bird a gun on condition that his village accept more priests, and more Jesuits come to help found a mission. Bird and Snow Falls grow into father and daughter as drought and war close in, until the Wendat face annihilation at the hands of the Haudenosaunee. Christophe is modelled on Jean de Brébeuf, co-founder of Sainte-Marie among the Hurons.", text_zh: "十七世纪初的温达克。故事由三个声音轮流讲述：伯德，一个家人被豪德诺索尼人杀害的温达特战士；雪落，一个豪德诺索尼女孩，伯德为了复仇杀了她的家人，把她掳来当女儿养；还有克里斯托夫，一个同样被伯德俘虏、被叫作“乌鸦”的法国耶稣会士。克里斯托夫起初因为身子孱弱、话也说不好而遭人取笑，却一心要让温达特人皈依；尚普兰送给伯德一支枪，条件是他的村子接纳更多神父，又有耶稣会士来帮忙建传教站。干旱和战争步步逼近，伯德和雪落渐渐成了真正的父女，直到温达特人在豪德诺索尼人手下面临灭顶之灾。克里斯托夫的原型是休伦人中的圣玛丽传教站的创建者之一让·德·布雷伯夫。", highlight_en: ["Wendake"], highlight_zh: ["温达克"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Orenda; https://muse.jhu.edu/article/587822/summary; https://reviewcanada.ca/magazine/2013/10/the-terror-and-pity-of-contact/; https://www.penguinrandomhouse.com/books/228121/the-orenda-by-joseph-boyden/9780385350747; https://thecanadianencyclopedia.ca/article/a-small-detour-from-an-epic-story/; https://www.powells.com/biblio/1-9780345806451-0; https://en.wikipedia.org/wiki/Sainte-Marie_among_the_Hurons" },
  { id: "essex-s1", kind: "scene", book_id: "essex-county", place_ids: ["ca-essex-county"], location: "Throughout", location_zh: "全书", text_en: "Three linked graphic stories set in the farm country of Essex County, Ontario. In Tales from the Farm, ten-year-old Lester, whose mother has died of cancer, goes to live with his uncle Ken on the farm, wears a mask and cape and draws his own comics, and against his uncle's wishes befriends Jimmy LeBeuf, who runs the local gas station after a head injury ended his career with the Toronto Maple Leafs in his first professional game. In Ghost Stories the deaf, aging Lou LeBeuf, Jimmy's great-uncle, looks back on the years when he and his brother Vince played hockey in Toronto. In The Country Nurse, Anne Quenneville makes her rounds of the county, looking in on Lou, Jimmy, Ken and Lester, and is more closely tied to the LeBeufs than she knows.", text_zh: "三个相互勾连的图像故事，发生在安大略埃塞克斯县的农田之间。《农场故事》里，十岁的莱斯特母亲死于癌症，被送到舅舅肯的农场上生活；他戴着面具、披着斗篷，自己画漫画，不顾舅舅反对，和吉米·勒伯夫交上了朋友：吉米曾效力多伦多枫叶队，却在第一场职业比赛里伤了头，从此只能在当地经营加油站。《鬼故事》里，吉米的叔祖、又聋又老的卢·勒伯夫回想当年他和弟弟文斯在多伦多打冰球的日子。《乡村护士》里，安妮·克内维尔在全县巡诊，探望卢、吉米、肯和莱斯特，她和勒伯夫一家的牵连比她自己知道的还要深。", highlight_en: ["Essex County"], highlight_zh: ["埃塞克斯县"], status: "draft", fact_source: "https://www.ebsco.com/research-starters/literature-and-writing/complete-essex-county; https://blogs.tpl.ca/agincourt/2010/07/book-review-essex-county-trilogy-by-jeff-lemire; https://quillandquire.com/review/essex-county-vol-1-tales-from-the-farm/; https://www.goodreads.com/book/show/18867840; https://www.criticsatlarge.ca/2014/06/tragi-comic-jeff-lemires-essex-county.html; https://en.wikipedia.org/wiki/Essex_County_Trilogy" },
  { id: "threeday-s1", kind: "scene", book_id: "three-day-road", place_ids: ["ca-moose-factory"], location: "Throughout", location_zh: "全书", text_en: "1919. Niska, an Oji-Cree healer and the last of her people to live off the land, has raised her nephew Xavier Bird and his friend Elijah Whiskeyjack in the old ways in the bush near Moose Factory. Told that Xavier has been killed in the war and Elijah is coming home, she paddles to meet the train in the town, and it is Xavier who steps off it, one leg gone and addicted to morphine. On the three-day canoe journey home she tells him the stories of her life to keep him alive, while he remembers how the two Cree boys enlisted in 1915, became feared snipers at Ypres and the Somme, and how Elijah changed. The title comes from Niska's teaching that those who are dying walk the three-day road.", text_zh: "1919 年。尼斯卡是一位奥吉布瓦-克里族的医者，也是她那一族最后一个靠土地为生的人，她在穆斯工厂附近的林子里，用老法子把侄子泽维尔·伯德和他的朋友以利亚·威士忌杰克带大。她听说泽维尔已经战死、以利亚要回来了，便划着独木舟到镇上去接火车，下车的却是泽维尔：一条腿没了，还染上了吗啡瘾。在三天的独木舟归途上，她给他讲自己一生的故事，想让他活下去；他则回忆两个克里族男孩怎样在 1915 年参军，怎样在伊珀尔和索姆河成了令人生畏的狙击手，以利亚又怎样变了一个人。书名来自尼斯卡的教导：将死之人要走三日之路。", highlight_en: ["Moose Factory"], highlight_zh: ["穆斯工厂"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Three_Day_Road; https://quillandquire.com/review/three-day-road/; https://mhs.mb.ca/docs/mb_history/59/threedayroad.shtml; https://www.thecanadianencyclopedia.ca/en/article/three-day-road; https://reviewcanada.ca/magazine/2005/06/cree-heroes-in-a-european-war/; https://www.litcharts.com/lit/three-day-road/summary" },
  { id: "livesgirls-s1", kind: "scene", book_id: "lives-of-girls-and-women", place_ids: ["ca-wingham"], location: "Throughout", location_zh: "全书", text_en: "Del Jordan grows up in the 1940s at the end of the Flats Road, outside the small Ontario town of Jubilee, where her father keeps silver foxes; the road, she says, is not part of town but not part of the country either. Her first companions are her younger brother Owen and Uncle Benny, an eccentric neighbour who is nobody's uncle. Her mother Ada, agnostic and opinionated, sells encyclopedias to the farmers and moves with Del into town, where Del lives among women: her mother, the boarder Fern Dogherty, her best friend Naomi. Through school, a search for a religion, the clever Jerry Storey and her first love, the Baptist Garnet French, Del works out what kind of woman she will be. Munro's only novel; Jubilee is drawn from Wingham, where she grew up.", text_zh: "二十世纪四十年代，德尔·乔丹在安大略小镇朱比利外弗拉茨路的尽头长大，父亲在那里养银狐；她说，这条路既不算镇上，也不算乡下。她最早的伙伴是弟弟欧文和本尼叔叔，一个谁的叔叔也不是的古怪邻居。母亲艾达不信神、主意多，向农民们推销百科全书，后来带着德尔搬进了镇里；德尔从此生活在女人们中间：母亲、房客弗恩·多尔蒂、好朋友娜奥米。经过学校、对宗教的一番追寻、聪明的杰里·斯托里，还有初恋、浸信会教徒加尼特·弗伦奇，德尔慢慢想明白自己要做一个什么样的女人。这是门罗唯一的长篇小说；朱比利取材于她长大的温厄姆。", highlight_en: ["Jubilee", "Ontario"], highlight_zh: ["朱比利", "安大略"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Lives_of_Girls_and_Women; https://www.supersummary.com/lives-of-girls-and-women/summary; https://www.penguinrandomhouse.com/books/118611; https://www.ebsco.com/research-starters/literature-and-writing/lives-girls-and-women-alice-munro; https://www.supersummary.com/lives-of-girls-and-women/symbols-and-motifs" },
  { id: "whodoyou-s1", kind: "scene", book_id: "who-do-you-think-you-are", place_ids: ["ca-wingham"], location: "Throughout", location_zh: "全书", text_en: "Ten linked stories of Rose, from girlhood to middle age, and her stepmother Flo. Rose grows up poor in West Hanratty, Ontario, with Flo and a father who beats her. At school in the better part of town she lies that she had half a grapefruit for breakfast, and the lie haunts her. A scholarship takes her to university, where Patrick, heir to a rich family, falls for her as a king falls for a beggar maid; she marries him, leaves him, becomes an actress, and at last comes home to Hanratty, where she finds an answer to the question the town has always asked: who do you think you are? It won the Governor General's Award in 1978 and was shortlisted for the Booker Prize in 1980 as The Beggar Maid.", text_zh: "十个相互勾连的故事，写罗丝从少女到中年，以及她的继母弗洛。罗丝在安大略的西汉拉蒂贫穷地长大，身边是弗洛和一个会打她的父亲。在镇上较体面那一头的学校里，她谎称早饭吃了半个葡萄柚，这个谎言一直纠缠着她。一份奖学金把她送进了大学，富家子弟帕特里克像国王爱上乞丐少女那样爱上了她；她嫁给了他，又离开了他，当了演员，最后回到汉拉蒂，在那里找到了小镇一直在问的那个问题的答案：你以为你是谁？此书获 1978 年总督奖，1980 年以《乞丐少女》之名入围布克奖短名单。", highlight_en: ["West Hanratty", "Ontario"], highlight_zh: ["西汉拉蒂", "安大略"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Who_Do_You_Think_You_Are%3F_(short_story_collection); https://ojs.library.ubc.ca/index.php/canlit/article/view/194216/190124; https://canlitguides.ca/?p=53500; https://canlitguides.ca/nadine-fladd/an-introduction-to-the-short-story-in-canada-reading-alice-munros-who-do-you-think-you-are/literary-analysis-of-the-short-story/; https://mookseandgripes.com/reviews/2015/02/18/alice-munro-royal-beatings/" }
];
